  freeNoSignup: { en: "Free · No sign-up · Runs in your browser", "pt-br": "Grátis · Sem cadastro · Roda no seu navegador", id: "Gratis · Tanpa daftar · Berjalan di browser Anda", "es-mx": "Gratis · Sin registro · Funciona en tu navegador", "es-co": "Gratis · Sin registro · Funciona en tu navegador", de: "Kostenlos · Keine Anmeldung · Läuft im Browser", fr: "Gratuit · Sans inscription · Fonctionne dans votre navigateur", it: "Gratis · Senza registrazione · Funziona nel browser" },
  heroPrivacyStrip: { en: "Most tools run right in your browser. Any tool that calls an external service says so on its page.", "pt-br": "A maioria das ferramentas roda direto no seu navegador. Qualquer ferramenta que use um serviço externo informa isso na própria página.", id: "Sebagian besar alat berjalan langsung di browser Anda. Alat apa pun yang memanggil layanan eksternal menyatakannya di halamannya.", "es-mx": "La mayoría de las herramientas funcionan directamente en tu navegador. Toda herramienta que use un servicio externo lo indica en su página.", "es-co": "La mayoría de las herramientas funcionan directamente en tu navegador. Toda herramienta que use un servicio externo lo indica en su página.", de: "Die meisten Tools laufen direkt in Ihrem Browser. Jedes Tool, das einen externen Dienst aufruft, weist auf seiner Seite darauf hin.", fr: "La plupart des outils fonctionnent directement dans votre navigateur. Tout outil qui fait appel à un service externe le signale sur sa page.", it: "La maggior parte degli strumenti funziona direttamente nel tuo browser. Ogni strumento che usa un servizio esterno lo dichiara nella sua pagina." },
  localProcessingDisclosed: { en: "Local processing — external calls disclosed on each tool page", "pt-br": "Processamento local — chamadas externas informadas em cada página", id: "Pemrosesan lokal — panggilan eksternal diungkapkan di setiap halaman alat", "es-mx": "Procesamiento local — llamadas externas reveladas en cada página", "es-co": "Procesamiento local — llamadas externas reveladas en cada página", de: "Lokale Verarbeitung – externe Aufrufe werden auf jeder Seite offengelegt", fr: "Traitement local — appels externes divulgués sur chaque page", it: "Elaborazione locale — chiamate esterne indicate in ogni pagina" },
  privacyNoticeDefault: { en: "All processing happens in your browser — your files never leave this device.", "pt-br": "Todo o processamento acontece no seu navegador — seus arquivos nunca saem deste dispositivo.", id: "Semua pemrosesan terjadi di browser Anda — file Anda tidak pernah meninggalkan perangkat ini.", "es-mx": "Todo el procesamiento ocurre en tu navegador — tus archivos nunca salen de este dispositivo.", "es-co": "Todo el procesamiento ocurre en tu navegador — tus archivos nunca salen de este dispositivo.", de: "Die gesamte Verarbeitung läuft in Ihrem Browser – Ihre Dateien verlassen dieses Gerät nie.", fr: "Tout le traitement se déroule dans votre navigateur — vos fichiers ne quittent jamais cet appareil.", it: "Tutta l'elaborazione avviene nel tuo browser — i tuoi file non lasciano mai questo dispositivo." },
  noSignup: { en: "No sign-up", "pt-br": "Sem cadastro", id: "Tanpa daftar", "es-mx": "Sin registro", "es-co": "Sin registro", de: "Keine Anmeldung", fr: "Sans inscription", it: "Senza registrazione" },
  noInstalls: { en: "No installs", "pt-br": "Sem instalação", id: "Tanpa instalasi", "es-mx": "Sin instalaciones", "es-co": "Sin instalaciones", de: "Keine Installation", fr: "Aucune installation", it: "Nessuna installazione" },
  popularToolsTitle: { en: "Popular tools", "pt-br": "Ferramentas populares", id: "Alat populer", "es-mx": "Herramientas populares", "es-co": "Herramientas populares", de: "Beliebte Tools", fr: "Outils populaires", it: "Strumenti popolari" },
  popularToolsSubtitle: { en: "The utilities people reach for most — done right, in your browser.", "pt-br": "As ferramentas mais usadas — feitas do jeito certo, no seu navegador.", id: "Utilitas yang paling sering dicari orang — dikerjakan dengan benar, di browser Anda.", "es-mx": "Las herramientas más usadas — hechas bien, en tu navegador.", "es-co": "Las herramientas más usadas — hechas bien, en tu navegador.", de: "Die am häufigsten genutzten Tools – richtig gemacht, direkt im Browser.", fr: "Les outils les plus utilisés — bien faits, dans votre navigateur.", it: "Gli strumenti più usati — fatti bene, nel tuo browser." },
  aboutClientSide: { en: "About client-side processing", "pt-br": "Sobre o processamento local", id: "Tentang pemrosesan lokal", "es-mx": "Acerca del procesamiento local", "es-co": "Acerca del procesamiento local", de: "Über die lokale Verarbeitung", fr: "À propos du traitement local", it: "Informazioni sull'elaborazione locale" },
  privacyBody: { en: "Your files are processed in your browser and are never stored on our servers. A few tools call external services — for example, PDF Translator sends just the extracted text to a translation service — and each tool page states exactly what happens to your data.", "pt-br": "Seus arquivos são processados no seu navegador e nunca são armazenados em nossos servidores. Algumas ferramentas chamam serviços externos — por exemplo, o Tradutor de PDF envia apenas o texto extraído a um serviço de tradução — e cada página informa exatamente o que acontece com seus dados.", id: "File Anda diproses di browser dan tidak pernah disimpan di server kami. Beberapa alat memanggil layanan eksternal — misalnya, Penerjemah PDF hanya mengirim teks yang diekstrak ke layanan terjemahan — dan setiap halaman alat menyatakan apa yang terjadi dengan data Anda.", "es-mx": "Tus archivos se procesan en tu navegador y nunca se almacenan en nuestros servidores. Algunas herramientas llaman a servicios externos — por ejemplo, el Traductor PDF envía solo el texto extraído a un servicio de traducción — y cada página indica exactamente qué ocurre con tus datos.", "es-co": "Tus archivos se procesan en tu navegador y nunca se almacenan en nuestros servidores. Algunas herramientas llaman servicios externos — por ejemplo, el Traductor PDF envía solo el texto extraído a un servicio de traducción — y cada página indica exactamente qué ocurre con tus datos.", de: "Ihre Dateien werden in Ihrem Browser verarbeitet und nie auf unseren Servern gespeichert. Einige Tools rufen externe Dienste auf – zum Beispiel sendet PDF übersetzen nur den extrahierten Text an einen Übersetzungsdienst – und jede Tool-Seite legt genau dar, was mit Ihren Daten geschieht.", fr: "Vos fichiers sont traités dans votre navigateur et ne sont jamais stockés sur nos serveurs. Quelques outils font appel à des services externes — par exemple, Traducteur PDF n'envoie que le texte extrait à un service de traduction — et chaque page indique exactement ce qu'il advient de vos données.", it: "I tuoi file vengono elaborati nel browser e non vengono mai salvati sui nostri server. Alcuni strumenti chiamano servizi esterni — ad esempio, Traduttore PDF invia solo il testo estratto a un servizio di traduzione — e ogni pagina indica esattamente cosa accade ai tuoi dati." },
  close: { en: "Close", "pt-br": "Fechar", id: "Tutup", "es-mx": "Cerrar", "es-co": "Cerrar", de: "Schließen", fr: "Fermer", it: "Chiudi" },
