  noMatchingTools: { en: "No Matching Tools Found", "pt-br": "Nenhuma Ferramenta Encontrada", id: "Tidak Ada Alat yang Cocok", "es-mx": "No Se Encontraron Herramientas", "es-co": "No Se Encontraron Herramientas", de: "Keine passenden Tools gefunden", fr: "Aucun outil correspondant trouvé", it: "Nessuno strumento corrispondente trovato" },
  noMatchingToolsBody: { en: "Try clearing your search query to find working creator tools.", "pt-br": "Tente limpar sua busca para encontrar ferramentas de criação funcionais.", id: "Coba hapus kata kunci pencarian Anda untuk menemukan alat kreator yang berfungsi.", "es-mx": "Intenta borrar tu búsqueda para encontrar herramientas de creación funcionales.", "es-co": "Intenta borrar tu búsqueda para encontrar herramientas de creación funcionales.", de: "Löschen Sie Ihre Suche, um funktionierende Creator-Tools zu finden.", fr: "Essayez d'effacer votre recherche pour trouver des outils de création fonctionnels.", it: "Prova a cancellare la ricerca per trovare strumenti di creazione funzionanti." },
  integrityPolicy: { en: "Integrity Policy", "pt-br": "Política de Integridade", id: "Kebijakan Integritas", "es-mx": "Política de Integridad", "es-co": "Política de Integridad", de: "Integritätsrichtlinie", fr: "Politique d'intégrité", it: "Politica di integrità" },
  integrityPolicyBody: { en: "Every tool listed on this page is live and fully functional — we do not advertise vaporware.", "pt-br": "Cada ferramenta listada nesta página é real e totalmente funcional — não anunciamos promessas vazias.", id: "Setiap alat yang terdaftar di halaman ini berfungsi penuh — kami tidak mengiklankan fitur yang belum ada.", "es-mx": "Cada herramienta listada en esta página es real y totalmente funcional — no anunciamos vaporware.", "es-co": "Cada herramienta listada en esta página es real y totalmente funcional — no anunciamos vaporware.", de: "Jedes auf dieser Seite gelistete Tool ist live und voll funktionsfähig — wir bewerben keine Luftschlösser.", fr: "Chaque outil listé sur cette page est réel et entièrement fonctionnel — nous ne faisons pas de publicité pour de la fumée.", it: "Ogni strumento elencato in questa pagina è reale e pienamente funzionante — non pubblicizziamo illusioni." },
  clientSide100: { en: "100% Client-Side", "pt-br": "100% Local no Navegador", id: "100% di Sisi Klien", "es-mx": "100% en el Navegador", "es-co": "100% en el Navegador", de: "100 % lokal", fr: "100 % côté client", it: "100% lato client" },
  clientSide100Body: { en: "Titles, descriptions and thumbnail frames are processed strictly inside your browser's local memory.", "pt-br": "Títulos, descrições e molduras de miniaturas são processados estritamente na memória local do seu navegador.", id: "Judul, deskripsi, dan bingkai thumbnail diproses sepenuhnya di memori lokal browser Anda.", "es-mx": "Los títulos, descripciones y marcos de miniaturas se procesan estrictamente en la memoria local de tu navegador.", "es-co": "Los títulos, descripciones y marcos de miniaturas se procesan estrictamente en la memoria local de tu navegador.", de: "Titel, Beschreibungen und Thumbnail-Rahmen werden ausschließlich im lokalen Speicher Ihres Browsers verarbeitet.", fr: "Les titres, descriptions et cadres de vignettes sont traités strictement dans la mémoire locale de votre navigateur.", it: "Titoli, descrizioni e cornici delle miniature vengono elaborati esclusivamente nella memoria locale del browser." },
  zeroUploads: { en: "Zero Uploads", "pt-br": "Zero Envios", id: "Nol Unggahan", "es-mx": "Cero Envíos", "es-co": "Cero Envíos", de: "Keine Uploads", fr: "Zéro téléversement", it: "Zero upload" },
  zeroUploadsBody: { en: "No tracking, no hidden data transmission, no fabricated metrics — what you compute stays with you.", "pt-br": "Sem rastreamento, sem transmissão oculta de dados, sem métricas inventadas — o que você calcula fica com você.", id: "Tanpa pelacakan, tanpa transmisi data tersembunyi, tanpa metrik palsu — apa yang Anda hitung tetap milik Anda.", "es-mx": "Sin rastreo, sin transmisión oculta de datos, sin métricas inventadas — lo que calculas se queda contigo.", "es-co": "Sin rastreo, sin transmisión oculta de datos, sin métricas inventadas — lo que calculas se queda contigo.", de: "Kein Tracking, keine versteckte Datenübertragung, keine erfundenen Metriken — was Sie berechnen, bleibt bei Ihnen.", fr: "Aucun suivi, aucune transmission cachée de données, aucune métrique inventée — ce que vous calculez reste chez vous.", it: "Nessun tracciamento, nessuna trasmissione nascosta di dati, nessuna metrica inventata — ciò che calcoli resta tuo." },
  honestLabels: { en: "Honest Labels", "pt-br": "Rótulos Honestos", id: "Label Jujur", "es-mx": "Etiquetas Honestas", "es-co": "Etiquetas Honestas", de: "Ehrliche Kennzeichnung", fr: "Étiquettes honnêtes", it: "Etichette oneste" },
  honestLabelsBody: { en: "Tools only appear here once they are complete. Anything not built yet is never shown as if it were.", "pt-br": "As ferramentas só aparecem aqui quando estão completas. Nada que ainda não foi criado é mostrado como se existisse.", id: "Alat hanya muncul di sini setelah selesai. Sesuatu yang belum dibuat tidak pernah ditampilkan seolah sudah ada.", "es-mx": "Las herramientas solo aparecen aquí una vez que están completas. Nada que aún no se haya creado se muestra como si existiera.", "es-co": "Las herramientas solo aparecen aquí una vez que están completas. Nada que aún no se haya creado se muestra como si existiera.", de: "Tools erscheinen hier erst, wenn sie fertig sind. Noch nicht Entwickeltes wird nie als vorhanden dargestellt.", fr: "Les outils n'apparaissent ici qu'une fois terminés. Rien qui n'est pas encore construit n'est présenté comme existant.", it: "Gli strumenti compaiono qui solo quando sono completi. Ciò che non è ancora realizzato non viene mai mostrato come se esistesse." },
  transparencyGuarantee: { en: "Transparency & Privacy Guarantee", "pt-br": "Garantia de Transparência e Privacidade", id: "Jaminan Transparansi & Privasi", "es-mx": "Garantía de Transparencia y Privacidad", "es-co": "Garantía de Transparencia y Privacidad", de: "Transparenz- & Datenschutzgarantie", fr: "Garantie de transparence et de confidentialité", it: "Garanzia di trasparenza e privacy" },
  transparencyGuaranteeBody: { en: "All creator tools run fully offline after the page loads. No data is ever logged, cached, or transmitted to external servers.", "pt-br": "Todas as ferramentas de criação funcionam totalmente offline após o carregamento da página. Nenhum dado é registrado, armazenado em cache ou transmitido a servidores externos.", id: "Semua alat kreator berjalan sepenuhnya offline setelah halaman dimuat. Tidak ada data yang pernah dicatat, di-cache, atau dikirim ke server eksternal.", "es-mx": "Todas las herramientas de creación funcionan totalmente offline después de cargar la página. Ningún dato se registra, almacena en caché ni transmite a servidores externos.", "es-co": "Todas las herramientas de creación funcionan totalmente offline después de cargar la página. Ningún dato se registra, almacena en caché ni transmite a servidores externos.", de: "Alle Creator-Tools laufen nach dem Laden der Seite vollständig offline. Es werden nie Daten protokolliert, zwischengespeichert oder an externe Server übertragen.", fr: "Tous les outils de création fonctionnent entièrement hors ligne une fois la page chargée. Aucune donnée n'est jamais enregistrée, mise en cache ni transmise à des serveurs externes.", it: "Tutti gli strumenti di creazione funzionano completamente offline dopo il caricamento della pagina. Nessun dato viene mai registrato, memorizzato nella cache o inviato a server esterni." },
  addedToFavoritesToast: { en: "Added to Favorites", "pt-br": "Adicionado aos Favoritos", id: "Ditambahkan ke Favorit", "es-mx": "Añadido a Favoritos", "es-co": "Añadido a Favoritos", de: "Zu Favoriten hinzugefügt", fr: "Ajouté aux favoris", it: "Aggiunto ai Preferiti" },
