  uploadFiles: { en: "Upload files", "pt-br": "Enviar arquivos", id: "Unggah file", "es-mx": "Subir archivos", "es-co": "Subir archivos", de: "Dateien hochladen", fr: "Téléverser des fichiers", it: "Carica file" },
  dropAnywhereTitle: { en: "Drop files anywhere to start processing!", "pt-br": "Solte os arquivos em qualquer lugar para começar!", id: "Letakkan file di mana saja untuk mulai memproses!", "es-mx": "¡Suelta los archivos en cualquier lugar para empezar!", "es-co": "¡Suelta los archivos en cualquier lugar para empezar!", de: "Legen Sie Dateien zum Starten irgendwohin ab!", fr: "Déposez des fichiers n'importe où pour commencer !", it: "Trascina i file ovunque per iniziare!" },
  dropAnywhereBody: { en: "Your assets will be loaded locally and never uploaded to any remote server.", "pt-br": "Seus arquivos serão carregados localmente e nunca enviados a um servidor remoto.", id: "Aset Anda akan dimuat secara lokal dan tidak pernah diunggah ke server mana pun.", "es-mx": "Tus archivos se cargarán localmente y nunca se subirán a ningún servidor remoto.", "es-co": "Tus archivos se cargarán localmente y nunca se subirán a ningún servidor remoto.", de: "Ihre Dateien werden lokal geladen und nie auf einen entfernten Server hochgeladen.", fr: "Vos fichiers sont chargés localement et ne sont jamais envoyés sur un serveur distant.", it: "I tuoi file vengono caricati localmente e mai inviati a un server remoto." },
  clickToBrowse: { en: "Click to Browse", "pt-br": "Clique para navegar", id: "Klik untuk Memilih", "es-mx": "Haz clic para explorar", "es-co": "Haz clic para explorar", de: "Klicken zum Durchsuchen", fr: "Cliquez pour parcourir", it: "Fai clic per sfogliare" },
  supportedFormatsPaste: { en: "Supported formats: {formats}. Paste directly from your clipboard supported.", "pt-br": "Formatos compatíveis: {formats}. Também é possível colar direto da área de transferência.", id: "Format yang didukung: {formats}. Tempel langsung dari clipboard juga didukung.", "es-mx": "Formatos compatibles: {formats}. También puedes pegar directamente desde el portapapeles.", "es-co": "Formatos compatibles: {formats}. También puedes pegar directamente desde el portapapeles.", de: "Unterstützte Formate: {formats}. Einfügen aus der Zwischenablage wird unterstützt.", fr: "Formats pris en charge : {formats}. Coller depuis le presse-papiers est également pris en charge.", it: "Formati supportati: {formats}. Incolla direttamente dagli appunti." },
