/** Look up a UI string id for the current locale, falling back to English. */
export const t = (key: string, locale: string): string => {
  const dict = UI[key];
  if (!dict) return "";
  const val = dict[locale as LocaleCode];
  if (val) return val;
  return dict.en;
};

/** Format a UI string with `{token}` placeholders. */
export const tf = (key: string, locale: string, tokens: Record<string, string>): string => {
  let out = t(key, locale);
  for (const [k, v] of Object.entries(tokens)) out = out.replace(`{${k}}`, v);
  return out;
};

const BROWSE_CATEGORY_KEY: Record<string, string> = {
  Popular: "catPopular",
  PDF: "catPdf",
  Images: "catImages",
  Media: "catMedia",
  Developer: "catDeveloper",
  Design: "catDesign",
  SEO: "catSeo",
  Security: "catSecurity",
  Creator: "catCreator",
  Converters: "catConverters",
};

/** Localized label for a Browse category id (e.g. "Popular", "PDF", "Images"). */
export const browseCategoryLabel = (category: string, locale: string): string => {
  const key = BROWSE_CATEGORY_KEY[category];
  const val = key ? t(key, locale) : "";
  return val || category;
};

